UPDATE businesses SET description = 'The Ditsong National Museum of Natural History, formerly the Transvaal Museum, was founded as the Staatsmuseum of the Zuid-Afrikaansche Republiek on 1 December 1892, making it one of the oldest museums in the country. It is the only natural history museum in Gauteng and one of the largest in South Africa, acting as custodian of a large part of the country''s natural heritage collections.

Its holdings include hominid fossils from the Cradle of Humankind World Heritage Site, among them the fossil skull nicknamed Mrs Ples, alongside fossils, skeletons, skins and mounted specimens of amphibians, fish, invertebrates, reptiles and mammals. The museum is unusual in offering the public a chance to view original fossil material that is usually kept away from view, and it is open daily from 7:30am to 4pm, except on Christmas Day and Good Friday.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://ditsong.org.za/en/our-museums/museum-of-natural-history/'), description_enriched_at = datetime('now') WHERE slug = 'ditsong-national-museum-of-natural-history-pretoria-central' AND description = 'The Ditsong National Museum of Natural History, formerly the Transvaal Museum, was established in 1892 and is the only natural history museum in Gauteng, holding hominid fossils from the Cradle of Humankind -- including the Mrs Ples skull -- alongside collections of amphibians, fish, reptiles and mammals.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
